const listRecipesUsingFood = `-- name: ListRecipesUsingFood :many
select r.name from recipes r
where r.household_id = $1
  and r.id in (
    select ri.recipe_id from recipe_ingredients ri
    where ri.household_id = $1 and ri.food_id = $2
  )
order by lower(r.name), r.id
`

type ListRecipesUsingFoodParams struct {
	HouseholdID pgtype.UUID
	FoodID      pgtype.UUID
}

func (q *Queries) ListRecipesUsingFood(ctx context.Context, arg *ListRecipesUsingFoodParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listRecipesUsingFood, arg.HouseholdID, arg.FoodID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		items = append(items, name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

